def execute(config, operation, value):
    if operation not in config["tools"]:
        raise PermissionError("tool_not_available")
    if operation == "read":
        return value
    if operation == "search":
        return "needle" in value
    if operation == "export":
        return {"result": value}
    raise PermissionError("unknown_tool")

